(()=>{const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const descriptions={'kids-color-story':'เรื่องสั้น 8 เรื่อง ภาพระบายสีและหน้าวาดต่อ ชวนเด็กสังเกต เลือก และเล่าเรื่องของตัวเอง','kids-add-subtract':'แบบฝึกบวกลบช่วง 0–20 รวม 400 ข้อ พร้อมเฉลย สำหรับฝึกทีละน้อย','kids-color-numbers':'รวมชุดนิทานระบายสีและแบบฝึกบวกลบ 68 หน้า สำหรับฝึกคิดและสร้างสรรค์','content-planner':'วางแผนคอนเทนต์ 30 วัน พร้อมตัวอย่างหัวข้อและคำสั่ง AI สำหรับร้านค้า','shop-work-kit':'ตาราง CSV 6 ชุด สำหรับเตรียมข้อมูลสินค้า ตรวจออเดอร์ และติดตามงาน'};const products=[{id:'chatgpt',name:'ChatGPT ทำงานจริง',group:'ai',category:'AI และการทำงาน',description:'คู่มือภาษาไทย 200 หน้า พร้อมแนวทางเขียนคำสั่ง เชื่อมต่อแอป และต่อยอดไอเดีย',image:'',price:null},...LAUNCH_PRODUCTS.map(p=>({...p,group:p.id.startsWith('kids-')?'kids':'tools',description:descriptions[p.id]||p.description}))];const url=p=>p.id==='chatgpt'?'/books/chatgpt/':'/books/?product='+encodeURIComponent(p.id);const grid=document.getElementById('product-grid');grid.innerHTML=products.filter(p=>!p.status||p.status==='published').map(p=>`<article class="product" data-group="${p.group}" data-search="${escape(p.name+' '+p.category+' '+p.description)}"><a class="cover" href="${url(p)}" aria-label="ดูรายละเอียด ${escape(p.name)}"><span class="tag">${p.group==='kids'?'กิจกรรมสำหรับครอบครัว':p.group==='ai'?'กำลังเตรียมเปิดขาย':'ไฟล์พร้อมปรับใช้'}</span>${p.image?`<img src="${escape(p.image)}" alt="ตัวอย่าง ${escape(p.name)}" loading="lazy">`:`<div class="book"><small>PAVNO DIGITAL</small>${p.id==='chatgpt'?'ChatGPT<br>ทำงานจริง':'WORK<br>SMARTER'}</div>`}</a><div class="copy"><div class="category">${escape(p.category)}</div><h3><a href="${url(p)}">${escape(p.name)}</a></h3><p class="description">${escape(p.description)}</p><div class="product-bottom"><span class="price">${p.price===null?'เร็ว ๆ นี้':'฿'+p.price}<small>${p.price===null?'ยังไม่กำหนดราคา':'ราคาที่เสนอสำหรับเปิดร้าน'}</small></span><a href="${url(p)}">ดูรายละเอียด ↗</a></div></div></article>`).join('');let group='all';const search=document.getElementById('search');function filter(){const term=search.value.trim().toLocaleLowerCase('th');let n=0;grid.querySelectorAll('.product').forEach(card=>{card.hidden=!((group==='all'||card.dataset.group===group)&&card.dataset.search.toLocaleLowerCase('th').includes(term));if(!card.hidden)n++});document.getElementById('empty').hidden=n>0;document.getElementById('count').textContent=`แสดง ${n} รายการ`}document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{group=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});filter()}));search.addEventListener('input',filter);filter();const menu=document.querySelector('.menu'),nav=document.getElementById('navigation');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{menu.setAttribute('aria-expanded','false');nav.classList.remove('open')}));})();
